import type { AjanSablon, Bolge, SablonKategori, Sektor } from "./ajanKatalog";
import type { PAdim, Prosedur } from "./ajanProsedurTip";

/**
 * Dünya pazarına yönelik hazır ajanlar (Intercom Fin, Sierra, Lindy, Relevance AI, Voiceflow galerilerinin
 * karşılığı): e-ticaret, SaaS, İK, emlak, hukuk, sağlık, sigorta, seyahat, eğitim, restoran, otel, BT, satış ve
 * abonelik. Arayüz dili Türkçe; senaryo ve yasal çerçeve globaldir (GDPR, UK GDPR, CCPA, HIPAA, ABD ve AB
 * pratikleri). Saat dilimi ve para birimi sabit değildir: ajan bunları sahibin Bilgi bölümünden alır.
 * Prosedürlerdeki adresler sahibin kendi sistemine göre değiştirilmek üzere yazılmıştır; her HTTP adımının
 * deneme yanıtı vardır (denemede çalışır, canlıda gerçek adres gerekir).
 */
type G = {
  id: string; ad: string; kategori: SablonKategori; sektor: Sektor; bolge: Bolge[]; kapak: string; simge: number; aciklama: string;
  rol: string; adimlar: string[]; sinirlar: string[]; karsilama: string; baslangiclar: string[]; etiketler: string[];
  devir?: string; kisisel?: boolean; yasak?: string[]; prosedur?: Prosedur[]; araclar?: AjanSablon["araclar"]; gerekli?: string[]; tetik?: AjanSablon["tetik"];
};
const S = (n: number) => `/gercek/galeri/3d${(n % 12) + 1}.webp`;
const H = (x: string) => `/gercek/havuz/gorsel/${x}.webp`;
const API = "https://api.sirketin.com";
const ORTAK = "Ziyaretçi hangi dilde yazıyorsa o dilde yanıt ver. Tarih ve saatleri Bilgi bölümündeki işletme saat dilimine göre, saat dilimini de yazarak ver; ziyaretçi başka bir saat dilimindeyse iki saati birlikte göster. Para birimini, fiyatları, süreleri ve kuralları yalnız Bilgi bölümünden ya da araç yanıtından al; uydurma, emin değilsen ekibe aktar. Yanıtların kısa olsun: en fazla dört cümle ya da kısa bir liste.";

const pr = (id: string, ad: string, ne: string, anahtarlar: string[], adimlar: PAdim[]): Prosedur => ({ id, ad, ne, anahtarlar, acik: true, iptal: true, gecis: true, adimlar, guncelleme: 0 });

const yap = (t: G): AjanSablon => ({
  id: t.id, ad: t.ad, kategori: t.kategori, sektor: t.sektor, bolge: t.bolge, kapak: t.kapak, simge: S(t.simge), aciklama: t.aciklama,
  araclar: t.araclar ?? {}, karsilama: t.karsilama, baslangiclar: t.baslangiclar, etiketler: t.etiketler,
  ...(t.gerekli ? { gerekli: t.gerekli } : {}), ...(t.tetik ? { tetik: t.tetik } : {}),
  ...(t.devir ? { devir: { acik: true, kurallar: t.devir } } : {}),
  ...(t.kisisel || t.yasak ? { koruma: { ...(t.kisisel ? { kisisel: true } : {}), ...(t.yasak ? { yasakKonular: t.yasak } : {}) } } : {}),
  ...(t.prosedur ? { prosedurler: t.prosedur } : {}),
  talimat: `${t.rol}\n\nÇalışma biçimin:\n${t.adimlar.map((a, i) => `${i + 1}. ${a}`).join("\n")}\n\nSınırlar:\n${t.sinirlar.map((s) => `- ${s}`).join("\n")}\n\n${ORTAK}`,
});

